ACMsg.MICROBIT_RESET = "Återställer micro:bit-kortet programmässigt, motsvarande att trycka på återställningsknappen.";
ACMsg.MICROBIT_SLEEP = "Pausar programmet i <b>ms</b> millisekunder.";
ACMsg.MICROBIT_RUNNING_TIME = "Returnerar den tid som förflutit sedan kortet startade, i millisekunder.";
ACMsg.MICROBIT_PANIC = "Visar felet <b>error_code</b> på LED-matrisen och återställer kortet.";
ACMsg.MICROBIT_TEMPERATURE = "Returnerar kortets ungefärliga temperatur i grader Celsius.";
ACMsg.MICROBIT_SET_VOLUME = "Sätter den globala ljudvolymen till värdet <b>volume</b> mellan 0 och 255.";
ACMsg.MICROBIT_WS2812_WRITE = "Skriver innehållet i bufferten <b>buf</b> till en WS2812-LED-remsa ansluten till <b>pin</b>. Bufferten måste vara bytes eller bytearray.";
ACMsg.MICROBIT_RUN_EVERY = "Schemalägg att köra en funktion med det intervall som anges av tidsargumenten. Varje argument motsvarar en annan tidsenhet och de läggs ihop. Så <b>run_every(min=1, s=30)</b> schemalägger callbacken var halvannan minut. När ett undantag kastas inuti callback-funktionen tas funktionen bort från schemat. För att undvika detta kan du fånga undantag med <b>try/except</b>. <b>run_every</b> kan också användas som en dekorator genom att placera den ovanför den funktion som ska schemaläggas.";
ACMsg.MICROBIT_SCALE = "Konverterar <b>value</b> från intervallet definierat av <b>from_low</b> och <b>from_high</b> till ett nytt intervall definierat av <b>to_low</b> och <b>to_high</b>.";
ACMsg.MICROBIT_RUN_EVERY_DECORATOR = "Schemalägger körningen av en funktion med det intervall som anges av tidsargumenten. Varje argument motsvarar en annan tidsenhet och de läggs ihop. Så <b>run_every(min=1, s=30)</b> schemalägger callbacken var halvannan minut. När ett undantag kastas i callback-funktionen avregistreras den. För att undvika detta kan du hantera undantag med <b>try/except</b>. <b>run_every</b> kan även användas som en funktion genom att skicka den funktion som ska schemaläggas som första argument.";
ACMsg.MICROBIT_DISPLAY = "Denna modul styr 5x5 LED-displayen på framsidan av ditt kort. Den kan användas för att visa bilder, animationer och även text.";
ACMsg.MICROBIT_DISPLAY_GET_PIXEL = "Returnerar ljusstyrkan för LED:n vid kolumn <b>x</b> och rad <b>y</b> som ett heltal mellan <b>0</b> (av) och <b>9</b> (ljus).";
ACMsg.MICROBIT_DISPLAY_SET_PIXEL = "Sätter ljusstyrkan för LED:n vid kolumn <b>x</b> och rad <b>y</b> till <b>value</b>, som måste vara ett heltal mellan <b>0</b> och <b>9</b>.";
ACMsg.MICROBIT_DISPLAY_CLEAR = "Sätter alla LED:ars ljusstyrka till <b>0</b> (av).";
ACMsg.MICROBIT_DISPLAY_SHOW = "Visa <b>image</b>.";
ACMsg.MICROBIT_DISPLAY_SHOW_ADVANCED = "Om <b>image</b> är en sträng, ett flyttal eller ett heltal visas bokstäver/siffror i följd. Annars, om <b>image</b> är en itererbar sekvens av bilder, visas dessa bilder i följd. Varje bokstav, siffra eller bild visas med <b>delay</b> millisekunder mellan dem. Om <b>wait</b> är <b>True</b> blockerar denna funktion tills animationen är klar, annars körs animationen i bakgrunden. Om <b>loop</b> är <b>True</b> upprepas animationen för alltid. Om <b>clear</b> är <b>True</b> rensas displayen efter att itereraren är slut. Observera att argumenten <b>wait</b>, <b>loop</b> och <b>clear</b> måste specificeras med sina nyckelord.";
ACMsg.MICROBIT_DISPLAY_SCROLL = "Skrollar <b>text</b> horisontellt på displayen. Om <b>text</b> är ett heltal eller flyttal konverteras det först till en sträng med <b>str()</b>. Parametern <b>delay</b> styr hur snabbt texten skrollar. Om <b>wait</b> är <b>True</b> blockerar funktionen tills animationen är klar, annars körs animationen i bakgrunden. Om <b>loop</b> är <b>True</b> upprepas animationen för alltid. Om <b>monospace</b> är <b>True</b> tar tecknen upp <b>5</b> pixelkolumner i bredd; annars finns exakt <b>1</b> tom pixelkolumn mellan varje tecken när de skrollar. Observera att argumenten <b>wait</b>, <b>loop</b> och <b>monospace</b> måste specificeras med sina nyckelord.";
ACMsg.MICROBIT_DISPLAY_ON = "Använd <b>on()</b> för att slå på displayen.";
ACMsg.MICROBIT_DISPLAY_OFF = "Använd <b>off()</b> för att stänga av displayen (så att du kan återanvända GPIO-stiften som är kopplade till displayen för andra ändamål).";
ACMsg.MICROBIT_DISPLAY_IS_ON = "Returnerar <b>True</b> om displayen är på, annars <b>False</b>.";
ACMsg.MICROBIT_DISPLAY_READ_LIGHT_LEVEL = "Använd displayens LED:ar i omvänd polaritet för att mäta mängden ljus som faller på displayen. Returnerar ett heltal mellan <b>0</b> och <b>255</b> som representerar ljusnivån; högre värde betyder mer ljus.";
ACMsg.MICROBIT_IMAGE = "Klassen <b>Image</b> används för att skapa bilder som enkelt kan visas på enhetens LED-matris. Med ett bildobjekt kan du visa det via <b>display</b>-API:t."
ACMsg.MICROBIT_IMAGE_CONSTRUCTOR_STR = "Om <b>string</b> används måste strängen bestå av siffror 0–9 ordnade i rader som beskriver bilden, till exempel: <pre>\n\nimage = Image('09090:'\n\t '99999:'\n\t '99999:'\n\t '09990:'\n\t '00900:')\n</pre> skapar en 5x5-bild av ett X. Radslutet indikeras av ett kolon."
ACMsg.MICROBIT_IMAGE_CONSTRUCTOR_BUF = "Denna metod skapar en tom bild med <b>width</b> kolumner och <b>height</b> rader. Parametern <b>buffer</b> kan vara en array av storleken <b>width</b> * <b>height</b> innehållande heltal från 0 till 9. Till exempel: <pre>\n\nImage(2, 2, b'\\x08\\x08\\x08\\x08')\nou\nImage(2, 2, bytearray([9,9,9,9]))\n\n</pre> skapar en 2x2-bild med ljusstyrka 9.";
ACMsg.MICROBIT_IMAGE_BUILTIN_SEQ = "Inbyggd sekvens av bilder (animation), till exempel <b>Image.ALL_CLOCKS</b> eller <b>Image.ALL_ARROWS</b>.";
ACMsg.MICROBIT_IMAGE_HEIGHT = "Returnerar bildens höjd (antal rader).";
ACMsg.MICROBIT_IMAGE_WIDTH = "Returnerar bildens bredd (antal kolumner).";
ACMsg.MICROBIT_IMAGE_COPY = "Returnerar en kopia av bilden.";
ACMsg.MICROBIT_IMAGE_INVERT = "Returnerar en ny bild med pixlarnas ljusstyrka inverterad.";
ACMsg.MICROBIT_IMAGE_GET_PIXEL = "Returnerar ljusstyrkan vid kolumn <b>x</b> och rad <b>y</b> som ett heltal från <b>0</b> till <b>9</b>.";
ACMsg.MICROBIT_IMAGE_SET_PIXEL = "Sätter ljusstyrkan vid kolumn <b>x</b> och rad <b>y</b> till <b>value</b> (ett heltal från <b>0</b> till <b>9</b>).";
ACMsg.MICROBIT_IMAGE_FILL = "Sätter alla pixlar till <b>value</b> (ett heltal från <b>0</b> till <b>9</b>).";
